  // A row of chips that scrolls sideways with no scrollbar (3.1.0): pointing near either end scrolls it, the wheel
  // scrolls it too, a fade shows there's more, and a chip I pick slides to the middle.
  function studioChipStrip(strip) {
    if (strip.wsStrip) return strip.wsStrip;
    let raf = 0, speed = 0;
    const edges = () => {
      const more = strip.scrollWidth > strip.clientWidth + 1;
      strip.classList.toggle('ws-fade-start', more && strip.scrollLeft > 1);
      strip.classList.toggle('ws-fade-end', more && strip.scrollLeft + strip.clientWidth < strip.scrollWidth - 1);
    };
    const step = () => {
      if (!speed) { raf = 0; return; }
      const before = strip.scrollLeft; strip.scrollLeft += speed; edges();
      if (strip.scrollLeft === before) { raf = 0; return; }
      raf = requestAnimationFrame(step);
    };
    strip.addEventListener('pointermove', event => {
      if (event.pointerType && event.pointerType !== 'mouse') return;
      if (strip.scrollWidth <= strip.clientWidth + 1) { speed = 0; return; }
      const box = strip.getBoundingClientRect(), zone = Math.min(44, box.width / 4);
      const into = event.clientX < box.left + zone ? -(box.left + zone - event.clientX) : event.clientX > box.right - zone ? event.clientX - (box.right - zone) : 0;
      speed = into ? Math.sign(into) * Math.max(1.5, Math.min(1, Math.abs(into) / zone) * 9) : 0;
      if (speed && !raf) raf = requestAnimationFrame(step);
    });
    strip.addEventListener('pointerleave', () => { speed = 0; });
    strip.addEventListener('pointerdown', () => { speed = 0; });
    strip.addEventListener('wheel', event => {
      if (strip.scrollWidth <= strip.clientWidth + 1 || Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
      event.preventDefault(); strip.scrollLeft += event.deltaY; edges();
    }, { passive: false });
    strip.addEventListener('scroll', edges, { passive: true });
    const api = {
      edges,
      centre(chip, smooth = true) {
        if (!chip || strip.scrollWidth <= strip.clientWidth + 1) { edges(); return; }
        const zoom = strip.currentCSSZoom || 1, box = strip.getBoundingClientRect(), one = chip.getBoundingClientRect();
        const left = Math.max(0, Math.min(strip.scrollWidth - strip.clientWidth, strip.scrollLeft + ((one.left + one.width / 2) - (box.left + box.width / 2)) / zoom));
        const motion = document.documentElement.getAttribute('data-wme-studio-motion'), still = !smooth || (motion && motion !== 'normal') || matchMedia('(prefers-reduced-motion: reduce)').matches;
        strip.scrollTo({ left, behavior: still ? 'auto' : 'smooth' });
        if (still) edges();
      }
    };
    strip.wsStrip = api;
    requestAnimationFrame(edges);
    return api;
  }
  function studioStripCSS() { return '.ws-fade-end{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 30px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 30px),transparent)}.ws-fade-start{-webkit-mask-image:linear-gradient(90deg,transparent,#000 30px);mask-image:linear-gradient(90deg,transparent,#000 30px)}.ws-fade-start.ws-fade-end{-webkit-mask-image:linear-gradient(90deg,transparent,#000 30px,#000 calc(100% - 30px),transparent);mask-image:linear-gradient(90deg,transparent,#000 30px,#000 calc(100% - 30px),transparent)}'; }



  // a <= b for release numbers (the changelog's "what's new since"): "2.3.0" <= "3.0.0".
  function versionAtMost(a, b) {
    const parts = value => String(value || '').trim().split('-')[0].split('.').map(part => parseInt(part, 10) || 0);
    const x = parts(a), y = parts(b);
    for (let i = 0; i < Math.max(x.length, y.length); i += 1) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) < (y[i] || 0);
    return true;
  }
  const UI_HOST_ID = 'wme-studio-userscript-ui';
  const LAUNCHER_HOST_ID = 'wme-studio-launcher-host';
  let studioUI = null, studioUIFixes = null;
  let studioLauncher = null;
  let studioPanelOpen = false;

  const STUDIO_LOGO_DATA_URI = studioPart('STUDIO_LOGO_DATA_URI');
  const studioLauncherIcon = `<img src="${STUDIO_LOGO_DATA_URI}" alt="" aria-hidden="true">`;
  const studioIcon = `<img src="${STUDIO_LOGO_DATA_URI}" alt="" aria-hidden="true">`;

  function uiRouteAllowed() {
    return /(?:^|\/)editor(?!\/sdk(?:\/|$))(?:\/|$)/i.test(location.pathname) || /^(?:\/[^/]+)?\/signin\/?$/i.test(location.pathname);
  }

  // Miniature editors for the Layout page, drawn from the real layouts at one tenth of a 1920 px window: satellite
  // ground with WME road colours, and Studio's header, rails and circles where each mode and preset puts them.
  function layoutThumb(kind) {
    const road = (d, color, width) => `<path d="${d}" stroke="#141a14" stroke-opacity=".55" stroke-width="${width + 1}"/><path d="${d}" stroke="${color}" stroke-width="${width}"/>`;
    // A plain, quiet ground: the islands and panels are what the picture is about.
    const map = `<rect class="t-bg" width="192" height="108"/><path class="t-grid" d="M0 27h192M0 54h192M0 81h192M48 0v108M96 0v108M144 0v108"/>`;
    const island = (x, y, w, h, r) => `<rect class="t-sh" x="${x}" y="${y + .9}" width="${w}" height="${h}" rx="${r}"/><rect class="t-ui" x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}"/>`;
    const bar = (x, y, w, cls = 't-ink', h = 1.2) => `<rect class="${cls}" x="${x}" y="${y}" width="${w}" height="${h}" rx="${h / 2}"/>`;
    const dot = (x, y, r = 1.05, cls = 't-ink') => `<circle class="${cls}" cx="${x}" cy="${y}" r="${r}"/>`;
    const plus = (x, y, s) => `<rect class="t-acc" x="${x}" y="${y}" width="${s}" height="${s}" rx="${s * .28}"/><path class="t-plus" d="M${x + s / 2} ${y + s * .27}v${s * .46}M${x + s * .27} ${y + s / 2}h${s * .46}"/>`;
    // header contents: menu, wordmark, search, then delete/undo/redo, Save, alerts/chat/apps and the avatar
    const headParts = (x, y, w, h, standard) => { const m = y + h / 2, r = x + w, a = standard ? 7 : 5.8;
      return bar(x + 2.4, m - 1.5, 2.6, 't-strong', .6) + bar(x + 2.4, m - .3, 2.6, 't-strong', .6) + bar(x + 2.4, m + .9, 2.6, 't-strong', .6) + bar(x + a, m - .95, standard ? 15.4 : 11.5, 't-strong', 1.9)
        + (standard ? `<rect class="t-soft" x="24" y="${m - 2.3}" width="45" height="4.6" rx="1.5"/>` + dot(26.6, m, .9) + bar(28.4, m - .55, 8.7, 't-ink', 1.1) : dot(x + 20.6, m, .9) + bar(x + 22.4, m - .55, 8.7, 't-ink', 1.1))
        + (standard ? [40, 35.8, 31.6] : [34.9, 31.3, 27.7]).map(v => dot(r - v, m, .85)).join('') + `<rect class="t-save" x="${r - (standard ? 28.5 : 25.5)}" y="${m - 2}" width="7.5" height="4" rx="1.2"/>`
        + (standard ? [16.5, 12.3, 8.2] : [14.5, 10.8, 7.1]).map(v => dot(r - v, m, .85)).join('') + dot(r - (standard ? 3.5 : 2.9), m, 1.8, 't-strong'); };
    const header = (x, y, w) => island(x, y, w, 6.4, 2.2) + headParts(x, y, w, 6.4);
    const nav = x => island(x, 30.2, 6.2, 48.1, 2.4) + plus(x + 1.1, 31.3, 4) + [39.5, 44.6, 49.6, 54.6, 60, 65, 70.1, 75.1].map(y => dot(x + 3.1, y)).join('');
    const tools = x => island(x, 31.1, 6.2, 46.6, 2.4) + `<rect class="t-on" x="${x + 1}" y="32" width="4.2" height="4.2" rx="1.2"/>` + [38.8, 43.8, 48.7, 54.3, 59.3, 64.3, 70.2, 74.5].map(y => dot(x + 3.1, y)).join('');
    const online = (x, y) => island(x - 3, y - 3, 6, 6, 3) + dot(x - .5, y - .5, .8) + dot(x + .9, y + .5, .7);
    const tile = (x, y) => island(x - 3, y - 3, 6, 6, 3) + `<circle class="t-ring" cx="${x}" cy="${y}" r="1.9"/><path class="t-arc" d="M${x} ${y - 1.9}a1.9 1.9 0 1 1-1.85 2.3"/>`;
    const footer = x => [[x, 11], [126.9, 3.1], [131.5, 3.8], [136.9, 9.8], [148.2, 4.3], [154, 7.2], [165.3, 3.1], [172.5, 9.5], [185.9, 4.5]].map(([left, width]) => bar(left, 106.6, width, 't-foot', .7)).join('');
    const request = (x, y) => island(x, y, 30, 44, 2.6) + dot(x + 4.6, y + 5, 2, 't-warn') + bar(x + 8.4, y + 3.3, 13, 't-strong', 1.6) + bar(x + 8.4, y + 6.2, 9) + `<rect class="t-soft" x="${x}" y="${y + 10}" width="30" height="4.4"/>` + bar(x + 3, y + 11.6, 8)
      + bar(x + 3, y + 17.6, 23) + bar(x + 3, y + 20.4, 19) + bar(x + 3, y + 23.2, 21) + `<rect class="t-soft" x="${x + 3}" y="${y + 27.5}" width="24" height="7" rx="1.4"/>` + bar(x + 5, y + 29.4, 10)
      + `<rect class="t-soft" x="${x + 3}" y="${y + 37.4}" width="11.2" height="4" rx="1.2"/><rect class="t-acc" x="${x + 15.8}" y="${y + 37.4}" width="11.2" height="4" rx="1.2"/>`;
    const chat = (x, y) => island(x, y, 27, 34, 2.6) + bar(x + 3, y + 3, 10, 't-strong', 1.6) + dot(x + 23.4, y + 3.8, .8)
      + `<rect class="t-soft" x="${x + 3}" y="${y + 8}" width="14" height="4.4" rx="1.8"/><rect class="t-acc" x="${x + 10}" y="${y + 14}" width="14" height="4.4" rx="1.8"/><rect class="t-soft" x="${x + 3}" y="${y + 20}" width="17" height="4.4" rx="1.8"/><rect class="t-soft" x="${x + 3}" y="${y + 27.4}" width="21" height="3.8" rx="1.9"/>`;
    // Drawn to scale, the islands of a 1920 × 1080 editor are a few pixels wide in a card: each one is drawn 1.6 times
    // larger, from the edge it is pinned to, so the layouts read at a glance (3.0.0).
    const K = 1.6, Z = (content, ax, ay) => `<g transform="translate(${ax} ${ay}) scale(${K}) translate(${-ax} ${-ay})">${content}</g>`;
    let ui;
    if (kind === 'standard') {
      const head = `<rect class="t-ui" x="-1" y="-1" width="194" height="8.4"/>` + headParts(0, 0, 192 / K, 7.4, true);
      const rail = `<rect class="t-ui" x="-1" y="7.4" width="9" height="102"/>` + plus(2, 10.7, 4) + bar(1.2, 19.2, 5.6, 't-soft', .5) + bar(1.2, 57.6, 5.6, 't-soft', .5)
        + [23.6, 32.1, 40.6, 48.9, 62].map(y => dot(4, y) + bar(2, y + 2, 4, 't-ink', .8)).join('');
      const buttons = [13, 18.5, 23.8, 29.4, 35, 40.5].map((y, i) => `<rect class="${i ? 't-ui' : 't-on'}" x="186.3" y="${y}" width="4.2" height="4.2" rx="1.2"/>` + (i ? dot(188.4, y + 2.1, .8) : '')).join('');
      const pill = `<rect class="t-ui" x="9.8" y="100.4" width="15.5" height="3.6" rx="1.8"/>` + dot(12, 102.2, .8) + bar(13.8, 101.7, 9.5, 't-ink', 1);
      const tilePill = `<rect class="t-ui" x="165" y="101.4" width="16" height="3.4" rx="1"/>` + dot(166.9, 103.1, .7, 't-acc') + bar(168.6, 102.6, 8.5, 't-ink', 1);
      ui = Z(rail, 0, 7.4) + Z(buttons, 190.5, 9 + 7.4 * K - 7.4) + Z(pill, 8 * K, 104) + Z(tilePill, 181, 104.8)
        + `<rect class="t-ui" x="8" y="105.5" width="185" height="3.5"/>` + footer(9.7).replaceAll('t-foot', 't-ink') + Z(head, 0, 0);
    } else {
      const top = kind === 'left-handed' || kind === 'review', left = kind === 'left-handed';
      const headW = (kind === 'wide' ? 191.2 : 127) / K, headY = top ? 1.5 : 3;
      const railY = top ? 30.2 : 54;
      const leftRail = left ? tools(1.2) : nav(1.2), rightRail = left ? nav(184.6) : tools(184.6);
      ui = footer(top ? 1.6 : 9) + Z(header(96 - headW / 2, headY, headW), 96, headY) + Z(leftRail, 1.2, railY) + Z(rightRail, 190.8, railY)
        + (top ? Z(online(187.7, 14.5), 190.7, 7.5) + Z(tile(187.7, 21.4), 190.7, 18.4 + 8 * (K - 1))
          : Z(online(4.3, 101.2), 1.3, 104.2) + Z(tile(187.7, 101.2), 190.7, 104.2))
        + (kind === 'review' ? Z(chat(11, 17), 12, 17) + Z(request(150, 26), 180, 26) : '');
    }
    return `<svg class="thumb" viewBox="0 0 192 108" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">${map}${ui}</svg>`;
  }

  // The editor's own user name, for bug reports and the update tour: from the SDK, else from what the page shows.
  function wmeUserName() {
    const page = typeof unsafeWindow === 'undefined' ? window : unsafeWindow;
    const text = value => (typeof value === 'string' ? value : typeof value === 'number' ? String(value) : '').replace(/\s+/g, ' ').trim();
    const tries = [
      () => studioSDK.value(api => api.State.getUserInfo()?.userName, null),
      () => { try { return page.getWmeSdk?.({ scriptId: 'wme-studio', scriptName: 'WME Studio' })?.State?.getUserInfo?.()?.userName; } catch (_) { return null; } },
      () => { const box = document.querySelector('wz-user-box'); return box && (box.getAttribute('user-name') || box.getAttribute('username') || box.getAttribute('name') || box.querySelector('[slot="label"], [slot="name"]')?.textContent || box.shadowRoot?.querySelector('.user-name, .username, [class*="userName"], [class*="user-name"]')?.textContent); },
      // Never the reporter's Username line in a request window (4.0.2), which has the same class names.
      () => [...document.querySelectorAll('#user-info .user-name, .user-info .user-name, [class*="userName--"], [class*="username--"]')].find(node => !node.closest('.problem-edit, [id^="ISSUE_WINDOW"], [data-testid="floating-window"]'))?.textContent
    ];
    for (const attempt of tries) {
      let name = '';
      try { name = text(attempt()); } catch (_) { name = ''; }
      if (name && name.length <= 60 && !/^(?:undefined|null|unknown|guest)$/i.test(name)) return name;
    }
    return '';
  }
